from itertools import product

# 9 coins, one heavier, 2 weighings: 3 groups of 3, then 1 v 1 inside the heavy group.
def strategy(heavy):
    groups = [[0, 1, 2], [3, 4, 5], [6, 7, 8]]
    # weighing 1: groups[0] vs groups[1]
    if heavy in groups[0]:
        cand = groups[0]
    elif heavy in groups[1]:
        cand = groups[1]
    else:
        cand = groups[2]
    # weighing 2: cand[0] vs cand[1]
    if heavy == cand[0]:
        return cand[0]
    if heavy == cand[1]:
        return cand[1]
    return cand[2]


good = sum(strategy(h) == h for h in range(9))
# information bound: 2 weighings give 3^2 = 9 distinguishable outcomes, so 9 is the max
print("CHECK identified %d/9 coins in 2 weighings, capacity 3^2=%d vs 9/9, 9" % (good, 3 ** 2))
